import {chooseNPCAppearance,cacheNPCAppearance,spriteGroupImage,npcPlacementIssue} from './npc-picker.js';

export function gameAuthoringWorkshop(api){
 const $=s=>document.querySelector(s),esc=api.esc,state={tab:'overview',pendingActor:null,resumeActor:null,resumeNPC:null};
 const hmRules=hmRulesWorkshop(api);
 const data=()=>authoring(api.project());
 const tabs=[['overview','Overview'],['source','Engine & source'],['scenes','Scenes'],['state','State'],['actors','NPCs'],['dialogue','Dialogue'],['items','Items'],['music','Music'],['hmrules','HM rules'],['presentation','Opening'],['options','Options'],['audit','Check']];
 function open(tab=state.tab){state.tab=tab;if(tab==='source'){api.source().open();return;}if(tab==='hmrules'){hmRules.open();return;}if(tab==='scenes'){api.scenes().open();return;}if(tab==='items'){api.items().open();return;}if(tab==='music'){api.music().open();return;}if(tab==='presentation'){api.presentation().open();return;}
  api.modal('Game maker',`<div class="studio-tabs" role="tablist">${tabs.map(([id,name])=>`<button type="button" role="tab" data-author-tab="${id}" aria-selected="${tab===id}" class="${tab===id?'active':''}">${name}</button>`).join('')}</div><div id="authorContent"></div>`,null,'Done');document.querySelectorAll('[data-author-tab]').forEach(b=>b.onclick=()=>open(b.dataset.authorTab));({overview,state:stateScreen,actors,dialogue,options,audit}[tab]||overview)();
 }
 function overview(){const a=data(),scenes=api.project().maps.flatMap(m=>m.markers.filter(n=>n.runtime?.action==='scene')),issues=authoringIssues(api.project());$('#authorContent').innerHTML=`<p>Create the game’s reusable definitions, then link them to maps and scenes. All tools work with project drafts; native export checks the opened ROM’s capabilities.</p><div class="studio-metrics"><span><b>${scenes.length}</b>scenes</span><span><b>${a.actors.length}</b>characters</span><span><b>${a.items.length}</b>items</span><span><b>${a.music.length}</b>music tracks</span></div><div class="map-tool-grid">${tabs.filter(([id])=>!['overview','audit'].includes(id)).map(([id,name])=>`<button type="button" data-author-go="${id}">${name}</button>`).join('')}</div><button id="authorCheck" type="button" class="full ${issues.length?'needs-attention':''}">${issues.length?issues.length+' fields need attention':'Check project & ROM capabilities'}</button><p class="hint-line">Music assets are packaged with projects, and only referenced tracks compile. Custom NPC art uses independent graphics slots. Native opening timelines, expanded player appearances and saved Options need a compatible code / save adapter.</p>`;document.querySelectorAll('[data-author-go]').forEach(b=>b.onclick=()=>open(b.dataset.authorGo));$('#authorCheck').onclick=()=>open('audit');}
 function stateScreen(){const a=data(),flags=api.project().questFlags?.filter(q=>!q.hidden)||[],used=(api.project().questFlags||[]).reduce((n,q)=>Math.max(n,q.slot+1),0);$('#authorContent').innerHTML=`<p>Stable named flags and counters for prerequisites, branches, difficulty and repeat interactions. Renaming preserves every link.</p><p class="studio-status">${used} / 1,024 project save bits reserved. Native story flags are separate.</p><div class="studio-actions"><button id="authorAddFlag" type="button">＋ Flag</button><button id="authorAddVariable" type="button">＋ Counter / variable</button><button id="authorTestState" type="button">Test state</button></div><h3>Flags</h3>${flags.map(q=>`<button data-author-flag="${q.id}" type="button" class="studio-record"><span><b>${esc(q.name)}</b><small>Stable project flag</small></span><small>Rename</small></button>`).join('')||'<p>No visible flags yet.</p>'}<h3>Counters & options</h3>${a.variables.map(v=>`<button data-author-variable="${v.id}" type="button" class="studio-record"><span><b>${esc(v.name)}</b><small>${v.kind} · 0–${2**v.bits-1} · ${v.bits} save bits</small></span><small>Rename</small></button>`).join('')||'<p>No counters yet.</p>'}`;$('#authorAddFlag').onclick=()=>editFlag();$('#authorAddVariable').onclick=()=>editVariable();$('#authorTestState').onclick=()=>api.scenes().testState();document.querySelectorAll('[data-author-flag]').forEach(b=>b.onclick=()=>editFlag(flags.find(q=>q.id===b.dataset.authorFlag)));document.querySelectorAll('[data-author-variable]').forEach(b=>b.onclick=()=>editVariable(a.variables.find(v=>v.id===b.dataset.authorVariable)));}
 function editFlag(old){api.modal(old?'Rename flag':'Create flag',`<label>Name<input id="authorFlagName" maxlength="80" value="${esc(old?.name||'')}" placeholder="Parcel delivered"></label><p>The internal ID remains stable when the name changes.</p>`,()=>{const name=$('#authorFlagName').value.trim();if(!name)throw Error('Give the flag a name.');api.change(()=>{if(old)old.name=name;else addQuestFlag(api.project(),name);});open('state');return false;},'Save flag');}
 function editVariable(old){api.modal(old?'Rename counter':'Create counter / variable',`<label>Name<input id="authorVariableName" maxlength="80" value="${esc(old?.name||'')}" placeholder="Times spoken to Wade"></label><label>Range<select id="authorVariableBits" ${old?'disabled':''}><option value="4" ${old?.bits===4?'selected':''}>0–15 · 4 bits</option><option value="8" ${!old||old.bits===8?'selected':''}>0–255 · 8 bits</option><option value="16" ${old?.bits===16?'selected':''}>0–65,535 · 16 bits</option></select></label><p>Native values persist with the game’s Save command. Counters saturate at their limits rather than wrapping.</p>`,()=>{const name=$('#authorVariableName').value.trim();if(!name)throw Error('Give the counter a name.');api.change(()=>{if(old)old.name=name;else addVariable(api.project(),name,{bits:+$('#authorVariableBits').value});});open('state');return false;},'Save counter');}
 function actors(){const a=data();$('#authorContent').innerHTML=`<p>Choose a ROM sprite or your own sprite group, then place an NPC with its own dialogue and scenes. Existing map NPCs are listed below.</p><div class="studio-actions"><button id="authorNewActor" type="button" class="primary">＋ Create character</button><button id="authorBrowseNPC" type="button">Browse existing sprites</button>${!api.session()?'<button id="authorNPCSource" type="button">Open source GBA ROM</button>':''}</div>${!api.session()?'<p class="studio-status needs-attention">Reopen the source ROM to browse its NPC sprites. Saved characters and placed NPCs remain in your project.</p>':''}<label>Find a character or NPC<input id="authorNPCSearch" type="search" placeholder="Name, map, or sprite number"></label><h3>Reusable characters</h3><div id="authorActorRows"></div><h3>NPCs on your maps</h3><label>Show<select id="authorNPCScope"><option value="all">All project maps</option><option value="current">Current map</option></select></label><div id="authorPlacedRows"></div>`;
  const draw=()=>{const query=$('#authorNPCSearch').value.toLowerCase();$('#authorActorRows').innerHTML=a.actors.filter(n=>(n.name+' '+(n.native?.graphics??'')).toLowerCase().includes(query)).map(n=>`<article class="studio-record"><span><b>${esc(n.name)}</b><small>${n.native?'ROM appearance #'+n.native.graphics:n.spriteGroupId?'Custom artwork · independent native slot':'Choose an appearance'}</small></span><div class="studio-actions"><button data-actor-place="${n.id}" type="button">Place</button><button data-actor-edit="${n.id}" type="button">Edit</button></div></article>`).join('')||'<p>No matching reusable characters yet.</p>';
   const placed=api.project().maps.flatMap(map=>map.markers.filter(n=>n.npc||n.rom?.type==='npc').map(n=>({map,n}))).filter(({map,n})=>($('#authorNPCScope').value!=='current'||map.id===api.map().id)&&(n.title+' '+map.name+' '+(n.npc?.graphics??n.rom?.sprite??'')).toLowerCase().includes(query));
   $('#authorPlacedRows').innerHTML=placed.slice(0,80).map(({map,n})=>`<article class="studio-record"><span><b>${esc(n.title)}</b><small>${esc(map.name)} · ${n.x}, ${n.y} · ${n.npc?'Placed NPC':'Imported NPC'}</small></span><div class="studio-actions"><button data-npc-edit="${n.id}" type="button">Select / edit</button><button data-npc-reuse="${n.id}" type="button">Reuse look</button></div></article>`).join('')||'<p>No matching NPCs. Import maps with NPC/event pins enabled to list the original characters.</p>';
   if(placed.length>80)$('#authorPlacedRows').insertAdjacentHTML('beforeend','<p>Showing 80 NPCs. Search or choose the current map to narrow the list.</p>');
   document.querySelectorAll('[data-actor-edit]').forEach(b=>b.onclick=()=>editActor(a.actors.find(n=>n.id===b.dataset.actorEdit)));document.querySelectorAll('[data-actor-place]').forEach(b=>b.onclick=()=>beginPlace(b.dataset.actorPlace));
   document.querySelectorAll('[data-npc-edit]').forEach(b=>b.onclick=()=>{const e=placed.find(e=>e.n.id===b.dataset.npcEdit);api.loadMap(e.map.id);editPlaced(e.n);});
   document.querySelectorAll('[data-npc-reuse]').forEach(b=>b.onclick=()=>{const {n}=placed.find(e=>e.n.id===b.dataset.npcReuse),t=api.session()?npcTemplates(api.session().reader).find(t=>t.graphics===(n.npc?.graphics??n.rom?.npcAppearance?.graphics??n.rom?.sprite)):null;editActor(null,{id:uid(),name:n.npc?.name||t?.name||n.title,facing:n.npc?.facing||'down',dialogue:'Hello there!',spriteGroupId:n.npc?.spriteGroupId||null,native:n.npc&&!n.npc.customOnly?structuredClone(n.npc):t?cacheNPCAppearance(api,t):null});});
  };$('#authorNPCSearch').oninput=draw;$('#authorNPCScope').onchange=draw;draw();$('#authorNewActor').onclick=()=>editActor();$('#authorBrowseNPC').onclick=()=>chooseNPCAppearance(api,{onPick:appearance=>editActor(null,{id:uid(),name:appearance.native?npcTemplates(api.session().reader).find(t=>t.graphics===appearance.native.graphics).name:api.project().spriteStudio.groups.find(g=>g.id===appearance.spriteGroupId).name,facing:'down',dialogue:'Hello there!',...appearance}),onBack:()=>open('actors'),onOpenROM:()=>api.pickROM('actors')});if($('#authorNPCSource'))$('#authorNPCSource').onclick=()=>api.pickROM('actors');
 }
 function beginPlace(id){const actor=data().actors.find(a=>a.id===id);if(!actor)return;state.pendingActor=id;api.close();api.mode('actorPlace');api.collapse();api.toast('Tap walkable ground to place '+actor.name+'.');}
 async function editActor(old=null,draft=null){const actor=draft||structuredClone(old||{id:uid(),name:'New character',facing:'down',dialogue:'Hello there!',spriteGroupId:null}),session=api.session(),templates=session?npcTemplates(session.reader):[],groups=api.project().spriteStudio?.groups.filter(g=>g.views.overworld)||[];api.modal('Character · '+actor.name,`<label>Name<input id="actorName" maxlength="80" value="${esc(actor.name)}"></label><label>Native appearance<select id="actorNative"><option value="">Choose later / use custom artwork</option>${templates.map(t=>`<option value="${t.graphics}" ${actor.native?.graphics===t.graphics?'selected':''}>${esc(t.name)}</option>`).join('')}</select></label><label>Custom sprite group (independent native slot)<select id="actorCustom"><option value="">Use native appearance</option>${groups.map(g=>`<option value="${g.id}" ${actor.spriteGroupId===g.id?'selected':''}>${esc(g.name)}</option>`).join('')}</select></label><div id="actorPreview" class="actor-preview"></div><div class="studio-actions"><button id="actorMakeArt" type="button">Make / edit character sprites</button><button id="actorPaintNative" type="button" ${actor.native?'':'disabled'}>Edit native appearance</button></div><label>Initial facing<select id="actorFacing">${['down','up','left','right'].map(d=>`<option value="${d}" ${actor.facing===d?'selected':''}>${d}</option>`).join('')}</select></label><label>Default dialogue<textarea id="actorDialogue" maxlength="4000">${esc(actor.dialogue||'')}</textarea></label><p class="hint-line">Native appearances work as new character instances. Custom groups install in separate native graphics slots on the supported source ROMs. Use one static frame or nine native overworld frames; colours fit the source field palettes. Edit native appearance changes that native style wherever it is used, with palette-sharing controls.</p>${old?'<button id="actorDuplicate" type="button">Duplicate character definition</button>':''}`,()=>{collect();persist();},'Save character');
  if(actor.native&&(!session||actor.native.sourceId!==session.id)){$('#actorNative').insertAdjacentHTML('beforeend',`<option value="saved" selected>Saved ROM appearance #${actor.native.graphics} · reopen its source to edit</option>`);}
  $('#actorPreview').insertAdjacentHTML('beforebegin','<div class="studio-actions"><button id="actorBrowseAppearance" type="button">Browse sprites with previews</button><button id="actorSourceROM" type="button">'+(session?'Change source ROM':'Open source GBA ROM')+'</button></div>');
  $('#actorBrowseAppearance').onclick=()=>{collect();chooseNPCAppearance(api,{onPick:appearance=>editActor(old,{...actor,...appearance}),onBack:()=>editActor(old,actor),onOpenROM:()=>openSource()});};
  function openSource(){state.resumeActor={oldId:old?.id||null,actor:structuredClone(actor)};api.pickROM('actors');}
  $('#actorSourceROM').onclick=()=>{collect();openSource();};
  function collect(){actor.name=$('#actorName').value.trim()||'New character';actor.facing=$('#actorFacing').value;actor.dialogue=$('#actorDialogue').value;actor.spriteGroupId=$('#actorCustom').value||null;if($('#actorNative').value!=='saved'){const t=$('#actorNative').value!==''?templates.find(t=>t.graphics===+$('#actorNative').value):null;actor.native=t?cacheNPCAppearance(api,t):null;}}
  function persist(){api.change(()=>{const rows=data().actors,index=rows.findIndex(n=>n.id===actor.id);if(index<0)rows.push(structuredClone(actor));else rows[index]=structuredClone(actor);});api.refresh();}
  const preview=()=>{const custom=groups.find(g=>g.id===$('#actorCustom').value),t=$('#actorNative').value!==''?templates.find(t=>t.graphics===+$('#actorNative').value):null,image=custom?spriteGroupImage(custom):t?npcImage(t):api.asset(actor.native?.assetId)?.data;$('#actorPreview').innerHTML=image?`<img src="${image}" width="48" height="96" alt="Character preview">`:'<span>Choose an appearance</span>';$('#actorPaintNative').disabled=!actor.native||actor.native.sourceId!==session?.id;};$('#actorNative').onchange=()=>{collect();preview();};$('#actorCustom').onchange=preview;preview();$('#actorMakeArt').onclick=()=>{collect();let group=api.project().spriteStudio?.groups.find(g=>g.id===actor.spriteGroupId);if(!group){api.change(()=>{group=makeSpriteGroup(actor.name,{human:true});studioData(api.project()).groups.push(group);actor.spriteGroupId=group.id;});}persist();api.sprites().open({kind:'custom',id:group.id,side:'overworld'});};$('#actorPaintNative').onclick=()=>{collect();persist();api.sprites().open({kind:'npc',id:actor.native.graphics,side:'front'});};if($('#actorDuplicate'))$('#actorDuplicate').onclick=()=>{collect();actor.id=uid();actor.name+=' copy';editActor(null,actor);};
 }
 function tapActor(x,y){
  const actor=data().actors.find(a=>a.id===state.pendingActor);if(!actor)return;
  const issue=npcPlacementIssue(api.project(),api.map(),x,y);if(issue){api.toast(issue);return;}
  if(movementAt(api.map(),x,y).collision){api.toast('Choose clear, walkable ground for the character.');return;}
  const session=api.session(),native=actor.native,template=native&&session?.id===native.sourceId?npcTemplates(session.reader).find(t=>t.graphics===native.graphics):null,group=api.project().spriteStudio?.groups.find(g=>g.id===actor.spriteGroupId),cached=api.asset(native?.assetId),image=group?spriteGroupImage(group):template?npcImage(template):cached?.data;
  if(!image){api.toast('Open the source ROM or choose an appearance in the character definition first.');return;}
  const n=newScene(api.project(),x,y),assetId=group?uid():native.assetId||'native-npc-'+native.sourceId+'-'+native.graphics;
  n.title=actor.name;n.kind='npc';n.runtime.steps[0].text=actor.dialogue||'Hello there!';
  n.npc={...(native||{}),name:actor.name,facing:actor.facing,actorId:actor.id,assetId,...(group?{customOnly:true,spriteGroupId:group.id}:{}),...(!native?{customOnly:true}:{})};
  api.change(()=>{
   if(!api.project().assets.some(a=>a.id===assetId)){
    if(api.project().assets.length>=512)throw Error('The project image limit has been reached.');
    api.project().assets.push({id:assetId,name:actor.name+' appearance',width:group?.views.overworld.width||template?.width||cached?.width||16,height:group?.views.overworld.height||template?.height||cached?.height||32,tileSize:16,data:image});
   }
   completionFlag(api.project(),n);api.map().markers.push(n);
  });
  state.pendingActor=null;api.mode('move');api.refresh();api.scenes().edit(n);
 }
 function editPlaced(old,draft=null){
  const map=api.project().maps.find(m=>m.markers.some(n=>n.id===old.id));if(!map)return;
  const n=draft||structuredClone(old),imported=n.rom?.type==='npc'&&!n.npc,s=api.session(),t=s?npcTemplates(s.reader).find(t=>t.graphics===(n.npc?.graphics??n.rom?.npcAppearance?.graphics??n.rom?.sprite)):null,asset=api.asset(n.npc?.assetId||n.rom?.npcAppearance?.assetId),image=asset?.data||(t?npcImage(t):null),facing=n.npc?.facing||n.rom?.npcAppearance?.facing||'keep';
  api.modal('NPC · '+n.title,`${image?'<div class="actor-preview"><img src="'+image+'" width="48" height="96" alt="NPC appearance"></div>':''}<label>Name<input id="placedNPCName" maxlength="120" value="${esc(n.title)}"></label><p>${esc(map.name)} · ${imported?'Imported game NPC':'Placed character'}</p><div class="field-row"><label>Tile X<input id="placedNPCX" type="number" min="0" max="${map.width-1}" value="${n.x}"></label><label>Tile Y<input id="placedNPCY" type="number" min="0" max="${map.height-1}" value="${n.y}"></label></div><label>Standing direction<select id="placedNPCFacing">${[...(imported?['keep']:[]),'down','up','left','right'].map(d=>`<option value="${d}" ${facing===d?'selected':''}>${d==='keep'?'Keep original movement':d}</option>`).join('')}</select></label><div class="studio-actions"><button id="placedNPCAppearance" type="button">Choose existing sprite / appearance</button><button id="placedNPCActions" type="button">Edit dialogue / actions</button><button id="placedNPCOnMap" type="button">Select on map</button></div><p class="hint-line">${imported?'Position and appearance edits keep the original script. Choosing a standing direction replaces its roaming movement. Saving new dialogue/actions replaces this NPC’s original interaction script.':'Appearance and facing apply to this placed NPC. Editing its dialogue/actions preserves the other characters.'}${n.npc?.customOnly?' Custom artwork installs as an independent native style; source field palette limits apply.':''}</p>`,()=>{collect();save();},'Save NPC');
  function collect(){n.title=$('#placedNPCName').value.trim()||'NPC';n.x=+$('#placedNPCX').value;n.y=+$('#placedNPCY').value;if(n.npc)n.npc.facing=$('#placedNPCFacing').value;else if(n.rom.npcAppearance||$('#placedNPCFacing').value!=='keep')n.rom.npcAppearance={...(n.rom.npcAppearance||{graphics:n.rom.sprite,sourceId:map.rom.sourceId}),facing:$('#placedNPCFacing').value};}
  function save(){if(!inBounds(map,n.x,n.y)||!Number.isInteger(n.x)||!Number.isInteger(n.y))throw Error('Choose a tile inside this map.');if(n.npc||n.x!==old.x||n.y!==old.y){const issue=npcPlacementIssue(api.project(),map,n.x,n.y,n.id);if(issue)throw Error(issue);if(movementAt(map,n.x,n.y,{ignoreFieldObjects:true}).collision)throw Error('Choose clear, walkable ground for the NPC.');}api.change(()=>Object.assign(old,structuredClone(n)));api.refresh();}
  $('#placedNPCAppearance').onclick=()=>{collect();chooseNPCAppearance(api,{allowCustom:!imported,onBack:()=>editPlaced(old,n),onOpenROM:()=>{state.resumeNPC={id:old.id,draft:n};api.pickROM('actors');},onPick:appearance=>{if(imported)n.rom.npcAppearance={...appearance.native,facing:n.rom.npcAppearance?.facing||'keep'};else if(appearance.native){n.npc={...n.npc,...appearance.native,customOnly:false};delete n.npc.spriteGroupId;}else{const g=api.project().spriteStudio.groups.find(g=>g.id===appearance.spriteGroupId),assetId=uid();if(api.project().assets.length>=512)throw Error('The project image limit has been reached.');api.change(()=>api.project().assets.push({id:assetId,name:g.name,width:g.views.overworld.width,height:g.views.overworld.height,tileSize:16,data:spriteGroupImage(g)}));n.npc={...n.npc,customOnly:true,spriteGroupId:g.id,assetId};}editPlaced(old,n);}});};
  $('#placedNPCActions').onclick=()=>{try{collect();save();if(old.runtime?.action==='scene')api.scenes().edit(old);else api.events().edit(old);}catch(e){api.error(e);}};
  $('#placedNPCOnMap').onclick=()=>{try{collect();save();api.close();api.focusNPC(map.id,old.id);}catch(e){api.error(e);}};
 }
 function resume(){if(state.resumeNPC){const pending=state.resumeNPC;state.resumeNPC=null;const old=api.project().maps.flatMap(m=>m.markers).find(n=>n.id===pending.id);if(old){editPlaced(old,pending.draft);return;}}if(state.resumeActor){const pending=state.resumeActor;state.resumeActor=null;editActor(data().actors.find(a=>a.id===pending.oldId)||null,pending.actor);return;}open('actors');}
 function dialogue(){const a=data();$('#authorContent').innerHTML='<p>Reusable text keeps the same stable link when renamed or edited. Scene actions can choose these entries.</p><button id="authorNewDialogue" type="button" class="primary">＋ Write dialogue</button>'+a.dialogues.map(d=>`<button type="button" class="studio-record" data-dialogue-edit="${d.id}"><span><b>${esc(d.name)}</b><small>${esc(d.text.slice(0,80))}</small></span></button>`).join('');$('#authorNewDialogue').onclick=()=>editDialogue();document.querySelectorAll('[data-dialogue-edit]').forEach(b=>b.onclick=()=>editDialogue(a.dialogues.find(d=>d.id===b.dataset.dialogueEdit)));}
 function editDialogue(old){api.modal('Reusable dialogue',`<label>Name<input id="authorDialogueName" maxlength="120" value="${esc(old?.name||'')}"></label><label>Text<textarea id="authorDialogueText" maxlength="8000">${esc(old?.text||'')}</textarea></label><p>Use scene branches for player answers and conditional dialogue. Native pages wrap at compile time.</p>`,()=>{const name=$('#authorDialogueName').value.trim()||'Dialogue',text=$('#authorDialogueText').value;api.change(()=>{if(old)Object.assign(old,{name,text});else data().dialogues.push({id:uid(),name,text});});open('dialogue');return false;},'Save dialogue');}
 function options(){const a=data();$('#authorContent').innerHTML=`<p>Custom settings are saved variables that scenes can test. Enabled entries appear in Options → PROJECT in the native game. You can also place a settings interaction on a map.</p><div class="studio-actions"><button id="authorNewOption" type="button">＋ Custom option</button><button id="authorPlaceSettings" type="button" ${a.options.length?'':'disabled'}>Place settings interaction</button></div>${a.options.map(o=>`<button data-option-edit="${o.id}" class="studio-record" type="button"><span><b>${esc(o.name)}</b><small>${o.values.map(esc).join(' / ')} · default: ${esc(o.values[0])} · ${o.nativeMenu===false?'map interaction only':'native Options'}</small></span></button>`).join('')}`;$('#authorNewOption').onclick=()=>editOption();document.querySelectorAll('[data-option-edit]').forEach(b=>b.onclick=()=>editOption(a.options.find(o=>o.id===b.dataset.optionEdit)));$('#authorPlaceSettings').onclick=()=>{api.scenes().state.pending={kind:'place'};api.scenes().state.newSettings=true;api.close();api.mode('scenePlace');api.scenes().flow();api.toast('Tap the settings sign / NPC tile.');};}
 function editOption(old){api.modal('Custom game option',`<label>Name<input id="authorOptionName" maxlength="80" value="${esc(old?.name||'')}" placeholder="Difficulty"></label><label>Choices · one per line<textarea id="authorOptionValues" maxlength="300">${esc(old?.values.join('\n')||'Normal\nHard')}</textarea></label><label class="check"><input id="authorOptionNative" type="checkbox" ${old?.nativeMenu===false?'':'checked'}> Include in the native Options menu</label><p>Use 2–4 choices. The first choice is the initial value (0); scene conditions can compare the linked option variable.</p>`,()=>{const name=$('#authorOptionName').value.trim()||'Game option',values=$('#authorOptionValues').value.split('\n').map(s=>s.trim()).filter(Boolean);if(values.length<2||values.length>4||values.some(v=>v.length>24))throw Error('Use two to four choices, up to 24 characters each.');api.change(()=>{if(old)Object.assign(old,{name,values,nativeMenu:$('#authorOptionNative').checked});else{const variable=addVariable(api.project(),name,{bits:4,kind:'option'});data().options.push({id:uid(),name,values,variableId:variable.id,nativeMenu:$('#authorOptionNative').checked});}});open('options');return false;},'Save option');}
 function settingsActions(){return data().options.map(o=>({id:uid(),type:'answers',text:o.name+'?',allowCancel:true,cancel:[],choices:o.values.map((value,i)=>({id:uid(),label:value,steps:[{id:uid(),type:'set',variableId:o.variableId,value:i},{id:uid(),type:'say',text:o.name+' set to '+value+'.'}]}))}));}
 function audit(){const a=data(),issues=authoringIssues(api.project(),{native:true}),used=usedAuthoring(api.project());for(const item of itemBindings(api.project()))for(const message of itemIssues(item,api.project()))issues.push({path:'Item / '+item.name,message,severity:'error'});$('#authorContent').innerHTML=`<p class="studio-status ${issues.length?'needs-attention':'ready'}">${issues.length?issues.length+' fields / capability limits to review':'Authoring references passed'}</p><div class="studio-metrics"><span><b>${used.music.size}/${a.music.length}</b>music used</span><span><b>${itemBindings(api.project()).length}/${a.items.length}</b>items selected</span></div>${issues.map(i=>`<article class="scene-condition needs-attention"><b>${esc(i.path)}</b><p>${esc(i.message)}</p></article>`).join('')}<p>Unused library assets remain in the project. ROM compilation also checks source identity, graphics capacity, event collisions and relocation bounds. Select an opening for installation, enable the expanded player selector, and place custom NPC styles to include them in native export. Unused drafts stay in the project.</p><div class="studio-actions"><button id="authorCompile" type="button" class="primary">Compile & review ROM</button><button id="authorProjectCheck" type="button">Full project check</button></div>`;$('#authorCompile').onclick=api.exportROM;$('#authorProjectCheck').onclick=api.check;}
 return{state,open,tapActor,editPlaced,resume,settingsActions};
}
